const MAX_BYTES=3*1024*1024,MAX_WAIT=86400;
const httpError=status=>Object.assign(new Error('address_research_unavailable'),{status});

// HTTP failures may be HTML generated by an edge, not JSON from the application.
// Read their status and bounded retry hint before touching the response body.
export function researchRetrySeconds(headers,status,now=Date.now()){
  if(![429,502,503,504].includes(status))return 0;
  const raw=(headers.get('retry-after')||'').trim();let seconds;
  if(/^\d{1,6}$/.test(raw))seconds=Number(raw);
  else if(/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} [A-Z][a-z]{2} \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(raw)){
    const target=Date.parse(raw),date=Date.parse(headers.get('date')||'');
    if(Number.isFinite(target)&&new Date(target).toUTCString()===raw)seconds=Math.max(0,Math.ceil((target-(Number.isFinite(date)?date:now))/1000));
  }
  return Number.isFinite(seconds)&&seconds>=0&&seconds<=MAX_WAIT?seconds:status===429?60:0;
}

async function readReport(response,signal){
  if(Number(response.headers.get('content-length'))>MAX_BYTES){await response.body?.cancel();throw new Error('research_response_limit');}
  const reader=response.body?.getReader();if(!reader)throw new Error('unsupported_research_report');
  const decoder=new TextDecoder(),parts=[];let bytes=0;
  const abort=()=>{reader.cancel(signal.reason).catch(()=>{});};signal.addEventListener('abort',abort,{once:true});
  try{
    while(true){signal.throwIfAborted();const {done,value}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>MAX_BYTES)throw new Error('research_response_limit');parts.push(decoder.decode(value,{stream:true}));}
    parts.push(decoder.decode());signal.throwIfAborted();
    try{return JSON.parse(parts.join(''));}catch{throw new Error('unsupported_research_report');}
  }finally{signal.removeEventListener('abort',abort);reader.cancel().catch(()=>{});reader.releaseLock();}
}

export function createResearchClient({fetcher=fetch,now=Date.now,timeoutMs=60000}={}){
  let until=0,status=0,generation=0,timer=null;const listeners=new Set(),pending=new Set();
  const remaining=()=>Math.max(0,Math.ceil((until-now())/1000));
  const snapshot=()=>({until,remaining:remaining(),status});
  function notify(){for(const listener of listeners)listener(snapshot());if(!remaining()||!listeners.size){clearInterval(timer);timer=null;}}
  function schedule(){if(remaining()&&listeners.size&&!timer)timer=setInterval(notify,1000);}
  function hold(response){const seconds=researchRetrySeconds(response.headers,response.status,now());if(seconds&&now()+seconds*1000>until){until=now()+seconds*1000;status=response.status;notify();schedule();}}
  return {
    remaining,snapshot,
    subscribe(listener){listeners.add(listener);listener(snapshot());schedule();return ()=>{listeners.delete(listener);if(!listeners.size){clearInterval(timer);timer=null;}};},
    reset(){generation++;for(const controller of pending)controller.abort();until=0;status=0;notify();},
    async request(url,{signal,credentials='same-origin'}={}){
      signal?.throwIfAborted();if(remaining())throw Object.assign(httpError(status),{retryUntil:until});
      const epoch=generation,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(new DOMException('Research deadline exceeded','TimeoutError')),timeoutMs);
      const combined=signal?AbortSignal.any([signal,controller.signal]):controller.signal;pending.add(controller);
      try{
        const response=await fetcher(url,{credentials,cache:'no-store',redirect:'error',headers:{accept:'application/json'},signal:combined});
        combined.throwIfAborted();if(epoch!==generation)throw new DOMException('Research context changed','AbortError');
        if(!response.ok){hold(response);await response.body?.cancel().catch(()=>{});throw Object.assign(httpError(response.status),{retryUntil:until});}
        const body=await readReport(response,combined);combined.throwIfAborted();if(epoch!==generation)throw new DOMException('Research context changed','AbortError');return body;
      }finally{clearTimeout(timeout);pending.delete(controller);}
    },
  };
}
